int main(void){unsigned char source[12]={45,90,113,0,161,73,37,44,7,8,9,10},copy[12]={0};c50_copy_bgra_row(copy,source,3);for(int x=0;x<3;x++){assert(!memcmp(copy+x*4,source+x*4,3));assert(copy[x*4+3]==255);}unsigned char h[54],p[64*36*4]={0};assert(!c50_bmp_header(h,0,0));assert(!c50_dims(8193,36,8193*4));assert(!c50_dims(64,36,255));assert(c50_bmp_header(h,64,36));assert(c50_bmp_valid(h,54+sizeof(p)));assert(!c50_bmp_valid(h,54+sizeof(p)-1));assert(!c50_nonblack(p,64,36,256));for(size_t i=0;i<sizeof(p);i+=4){p[i]=45;p[i+1]=90;p[i+2]=113;p[i+3]=255;}assert(c50_nonblack(p,64,36,256));h[28]=24;assert(!c50_bmp_valid(h,54+sizeof(p)));h[28]=32;c50_le32(h+22,36);assert(!c50_bmp_valid(h,54+sizeof(p)));assert(c50_result(100,200,1,0,1,1,0)==C50_WAIT);assert(c50_result(100,8100,1,0,1,1,0)==C50_TIMEOUT);assert(c50_result(100,200,0,1,1,1,1)==C50_COMMIT);assert(c50_result(100,200,0,1,0,1,1)==C50_DISCARD);assert(c50_result(100,200,0,1,1,0,1)==C50_DISCARD);assert(c50_result(100,200,0,0,1,1,1)==C50_DISCARD);puts("PASS BMP header/size/pitch bounds and black frame validation, top-down 32-bit layout, lifecycle decisions.");}
